// runOnceForAllItems — construit un item par (post × réseau) avec le payload Blotato complet
const posts = $('Airtable — Lire validés').all().map(i => i.json);
const configRows = $('Airtable — Lire Config Blotato').all().map(i => i.json);
const accountsRow = configRows.find(r => r.Cle === 'BLOTATO_ACCOUNTS');
let accounts = {};
try { accounts = JSON.parse(accountsRow?.Valeur || '{}'); } catch(e) {}

const NET_TO_PLATFORM = { fb:'facebook', ig:'instagram', tiktok:'tiktok', youtube:'youtube', linkedin:'linkedin', x:'twitter' };
const PLATFORM_TO_TEXTFIELD = { facebook:'Texte_Facebook', instagram:'Texte_Instagram', linkedin:'Texte_LinkedIn', twitter:'Texte_X', tiktok:'Texte_TikTok', youtube:'Texte_YouTube' };

const results = [];
for (const post of posts) {
  const networks = post.Reseaux_Cibles || [];
  const mediaUrls = (() => { try { return JSON.parse(post.Visuels_URLs || '[]'); } catch(e) { return []; } })();
  for (const net of networks) {
    const platform = NET_TO_PLATFORM[net];
    if (!platform) continue;
    const acc = accounts[platform];
    if (!acc || !acc.accountId || acc.accountId === '__FILL_ME__') {
      results.push({ json: { _skip: true, recordId: post.id, platform, reason: 'accountId manquant' } });
      continue;
    }
    const text = post[PLATFORM_TO_TEXTFIELD[platform]] || post.Contenu_Texte || '';
    let target = { targetType: platform };
    if (platform === 'facebook' && acc.pageId) target.pageId = acc.pageId;
    if (platform === 'linkedin' && acc.pageId) target.pageId = acc.pageId;
    if (platform === 'tiktok') Object.assign(target, { isYourBrand:false, autoAddMusic:true, disabledDuet:false, privacyLevel:'PUBLIC_TO_EVERYONE', isAiGenerated:true, disabledStitch:false, disabledComments:false, isBrandedContent:false });
    if (platform === 'youtube') Object.assign(target, { title:(post.Titre||'Max-Morrys').substring(0,100), privacyStatus:'public', shouldNotifySubscribers:true, isMadeForKids:false, isAiGenerated:true });
    results.push({ json: {
      recordId: post.id,
      platform,
      network: net,
      body: {
        post: {
          accountId: acc.accountId,
          content: { text, mediaUrls, platform },
          target
        }
      }
    }});
  }
}
return results.length ? results : [{ json: { _empty: true }}];

// runOnceForEachItem — merge Blotato response with post record, accumulate postSubmissionIds JSON
const resp = $input.item.json;
const src = $('Build — Payloads Blotato').all()[$itemIndex].json;
if (src._skip || src._empty) return { json: { _skip: true }};
const postId = resp.postSubmissionId || resp.id || null;
return { json: {
  id: src.recordId,
  network: src.network,
  platform: src.platform,
  postSubmissionId: postId,
  Status: 'en_publication'
}};

// runOnceForAllItems — group submissions by recordId
const items = $input.all().map(i => i.json).filter(i => !i._skip);
const byId = {};
for (const it of items) {
  if (!byId[it.id]) byId[it.id] = { id: it.id, submissions: {}, Status: 'en_publication' };
  if (it.postSubmissionId) byId[it.id].submissions[it.network] = it.postSubmissionId;
}
return Object.values(byId).map(g => ({ json: {
  id: g.id,
  Blotato_PostSubmissionIDs: JSON.stringify(g.submissions),
  Status: g.Status
}}));
